import random
from collections import deque

def generate_random_cubic_graph(n):
    # Use configuration model
    # Create 3 copies of each vertex
    stubs = [v for v in range(n) for _ in range(3)]
    while True:
        random.shuffle(stubs)
        edges = set()
        valid = True
        for i in range(0, len(stubs), 2):
            u = stubs[i]
            v = stubs[i+1]
            if u == v:
                valid = False
                break
            if u > v:
                u, v = v, u
            if (u, v) in edges:
                valid = False
                break
            edges.add((u, v))
        if not valid:
            continue
        # Check degrees
        deg = [0]*n
        for u, v in edges:
            deg[u] += 1
            deg[v] += 1
        if all(d == 3 for d in deg):
            return list(edges)

def girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    best = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best == 3:
            return 3
    return best if best != float('inf') else -1

n = 24
random.seed(0)
for attempt in range(20000):
    edges = generate_random_cubic_graph(n)
    g = girth(n, edges)
    if g >= 7:
        print(f"Found after {attempt} attempts")
        print(f"Girth: {g}")
        print(f"Number of edges: {len(edges)}")
        # sort edges
        edges_sorted = sorted(edges)
        print(edges_sorted)
        break
else:
    print("Not found in 20000 attempts")

